初始化textfield并设置位置及大小UITextField *text = [[UITextField alloc]initWithFrame:CGRectMake(20, 20, 130, 30)]; 设置边框样式，只有设置了才会显示边框样式 1234567891011text.borderStyle = UITextBorderStyleRoundedRect; typedef enum &#123; UITextBorderStyleNone, UITextBorderStyleLine, UITextBorderStyleBezel, UITextBorderStyleRoundedRect &#125; UITextBorderStyle; 设置输入框的背景颜色，此时设置为白色 如果使用了自定义的背景图片边框会被忽略掉text.backgroundColor = [UIColor whiteColor]; 设置背景text.background = [UIImage imageNamed:@&quot;dd.png&quot;]; 设置背景text.disabledBackground = [UIImage imageNamed:@&quot;cc.png&quot;]; 当输入框没有内容时，水印提示 提示内容为passwordtext.placeholder = @&quot;password&quot;; 设置输入框内容的字体样式和大小text.font = [UIFont fontWithName:@&quot;Arial&quot; size:20.0f]; 设置字体颜色text.textColor = [UIColor redColor]; 输入框中是否有个叉号，在什么时候显示，用于一次性删除输入框中的内容 123456789101112text.clearButtonMode = UITextFieldViewModeAlways; typedef enum &#123; UITextFieldViewModeNever, // 重不出现 UITextFieldViewModeWhileEditing, //编辑时出现 UITextFieldViewModeUnlessEditing, // 除了编辑外都出现 UITextFieldViewModeAlways // 一直出现 &#125; UITextFieldViewMode; 输入框中一开始就有的文字text.text = @&quot;一开始就在输入框的文字&quot;; 每输入一个字符就变成点 用语密码输入text.secureTextEntry = YES; 是否纠错 12345678910text.autocorrectionType = UITextAutocorrectionTypeNo; typedef enum &#123; UITextAutocorrectionTypeDefault, // 默认 UITextAutocorrectionTypeNo, // 不自动纠错 UITextAutocorrectionTypeYes, // 自动纠错 &#125; UITextAutocorrectionType; 再次编辑就清空text.clearsOnBeginEditing = YES; 内容对齐方式text.textAlignment = UITextAlignmentLeft; 内容的垂直对齐方式 UITextField继承自UIControl, 此类中有一个属性contentVerticalAlignmenttext.contentVerticalAlignment = UIControlContentVerticalAlignmentCenter; 设置为YES时文本会自动缩小以适应文本窗口大小.默认是保持原来大小,而让长文本滚动textFied.adjustsFontSizeToFitWidth = YES; 设置自动缩小显示的最小字体大小text.minimumFontSize = 20; 设置键盘的样式 1234567891011121314151617181920212223242526text.keyboardType = UIKeyboardTypeNumberPad; typedef enum &#123; UIKeyboardTypeDefault, // 默认键盘，支持所有字符 UIKeyboardTypeASCIICapable, // 支持ASCII的默认键盘 UIKeyboardTypeNumbersAndPunctuation, // 标准电话键盘，支持＋＊＃字符 UIKeyboardTypeURL, // URL键盘，支持.com按钮 只支持URL字符 UIKeyboardTypeNumberPad, // 数字键盘 UIKeyboardTypePhonePad, // 电话键盘 UIKeyboardTypeNamePhonePad, // 电话键盘，也支持输入人名 UIKeyboardTypeEmailAddress, // 用于输入电子 邮件地址的键盘 UIKeyboardTypeDecimalPad, // 数字键盘 有数字和小数点 UIKeyboardTypeTwitter, // 优化的键盘，方便输入@、#字符 UIKeyboardTypeAlphabet = UIKeyboardTypeASCIICapable, &#125; UIKeyboardType; 首字母是否大写 123456789101112text.autocapitalizationType = UITextAutocapitalizationTypeNone; typedef enum &#123; UITextAutocapitalizationTypeNone, // 不自动大写 UITextAutocapitalizationTypeWords, // 单词首字母大写 UITextAutocapitalizationTypeSentences, // 句子的首字母大写 UITextAutocapitalizationTypeAllCharacters, // 所有字母都大写 &#125; UITextAutocapitalizationType; return键变成什么键 1234567891011121314151617181920212223242526text.returnKeyType =UIReturnKeyDone; typedef enum &#123; UIReturnKeyDefault, // 默认 灰色按钮，标有Return UIReturnKeyGo, // 标有Go的蓝色按钮 UIReturnKeyGoogle, // 标有Google的蓝色按钮，用语搜索 UIReturnKeyJoin, // 标有Join的蓝色按钮 UIReturnKeyNext, // 标有Next的蓝色按钮 UIReturnKeyRoute, // 标有Route的蓝色按钮 UIReturnKeySearch, // 标有Search的蓝色按钮 UIReturnKeySend, // 标有Send的蓝色按钮 UIReturnKeyYahoo, // 标有Yahoo的蓝色按钮 UIReturnKeyYahoo, // 标有Yahoo的蓝色按钮 UIReturnKeyEmergencyCall, // 紧急呼叫按钮 &#125; UIReturnKeyType; 键盘外观 12345678textView.keyboardAppearance=UIKeyboardAppearanceDefault； typedef enum &#123; UIKeyboardAppearanceDefault， // 默认外观，浅灰色 UIKeyboardAppearanceAlert，// 深灰 石墨色 &#125; UIReturnKeyType; 设置代理 用于实现协议text.delegate = self; 把textfield加到视图中[self.window addSubview:text]; 最右侧加图片是以下代码 左侧类似 1234567891011121314UIImageView *image=[[UIImageView alloc] initWithImage:[UIImage imageNamed:@&quot;right.png&quot;]]; text.rightView=image; text.rightViewMode = UITextFieldViewModeAlways; typedef enum &#123; UITextFieldViewModeNever, UITextFieldViewModeWhileEditing, UITextFieldViewModeUnlessEditing, UITextFieldViewModeAlways &#125; UITextFieldViewMode; 按return键键盘往下收 becomeFirstResponder类要采用UITextFieldDelegate协议 text.delegate = self; 声明text的代理是我，我会去实现把键盘往下收的方法 这个方法在UITextFieldDelegate里所以我们要采用UITextFieldDelegate这个协议 12345- (BOOL)textFieldShouldReturn:(UITextField *)textField &#123; [text resignFirstResponder]; //主要是[receiver resignFirstResponder]在哪调用就能把receiver对应的键盘往下收 return YES; &#125; 重写绘制行为除了UITextField对象的风格选项，你还可以定制化UITextField对象，为他添加许多不同的重写方法，来改变文本字段的显示行为。这些方法都会返回一个CGRect结构，制定了文本字段每个部件的边界范围。以下方法都可以重写。 textRectForBounds: &#x2F;&#x2F; 重写来重置文字区域 drawTextInRect: &#x2F;&#x2F; 改变绘文字属性.重写时调用super可以按默认图形属性绘制,若自己完全重写绘制函数，就不用调用super了. placeholderRectForBounds: &#x2F;&#x2F; 重写来重置占位符区域 drawPlaceholderInRect: &#x2F;&#x2F; 重写改变绘制占位符属性.重写时调用super可以按默认图形属性绘制,若自己完全重写绘制函数，就不用调用super了. borderRectForBounds: &#x2F;&#x2F; 重写来重置边缘区域 editingRectForBounds: &#x2F;&#x2F; 重写来重置编辑区域 clearButtonRectForBounds: &#x2F;&#x2F; 重写来重置clearButton位置,改变size可能导致button的图片失真 leftViewRectForBounds: rightViewRectForBounds: 委托方法123456789101112131415161718192021222324252627282930313233343536373839- (BOOL)textFieldShouldBeginEditing:(UITextField *)textField&#123; //返回一个BOOL值，指定是否循序文本字段开始编辑 return YES;&#125;- (void)textFieldDidBeginEditing:(UITextField *)textField&#123; //开始编辑时触发，文本字段将成为first responder &#125; - (BOOL)textFieldShouldEndEditing:(UITextField *)textField&#123; //返回BOOL值，指定是否允许文本字段结束编辑，当编辑结束，文本字段会让出first responder //要想在用户结束编辑时阻止文本字段消失，可以返回NO //这对一些文本字段必须始终保持活跃状态的程序很有用，比如即时消息 return NO;&#125;- (BOOL)textField:(UITextField\*)textField shouldChangeCharactersInRange:(NSRange)range replacementString:(NSString *)string&#123; //当用户使用自动更正功能，把输入的文字修改为推荐的文字时，就会调用这个方法。 //这对于想要加入撤销选项的应用程序特别有用 //可以跟踪字段内所做的最后一次修改，也可以对所有编辑做日志记录,用作审计用途。 //要防止文字被改变可以返回NO //这个方法的参数中有一个NSRange对象，指明了被改变文字的位置，建议修改的文本也在其中 return YES; &#125; - (BOOL)textFieldShouldClear:(UITextField \*)textField&#123; //返回一个BOOL值指明是否允许根据用户请求清除内容 //可以设置在特定条件下才允许清除内容 return YES; &#125; -(BOOL)textFieldShouldReturn:(UITextField \*)textField&#123; //返回一个BOOL值，指明是否允许在按下回车键时结束编辑 //如果允许要调用resignFirstResponder 方法，这回导致结束编辑，而键盘会被收起[textField resignFirstResponder]; //查一下resign这个单词的意思就明白这个方法了 return YES; &#125; 通知UITextField派生自UIControl，所以UIControl类中的通知系统在文本字段中也可以使用。除了UIControl类的标准事件，你还可以使用下列UITextField类特有的事件 UITextFieldTextDidBeginEditingNotification UITextFieldTextDidChangeNotification UITextFieldTextDidEndEditingNotification 当文本字段退出编辑模式时触发。通知的object属性存储了最终文本。因为文本字段要使用键盘输入文字，所以下面这些事件发生时，也会发送动作通知 UIKeyboardWillShowNotification &#x2F;&#x2F;键盘显示之前发送 UIKeyboardDidShowNotification &#x2F;&#x2F;键盘显示之后发送 UIKeyboardWillHideNotification &#x2F;&#x2F;键盘隐藏之前发送 UIKeyboardDidHideNotification &#x2F;&#x2F;键盘隐藏之后发送 限制只能输入特定的字符 12345678(BOOL)textField:(UITextField *)textField shouldChangeCharactersInRange:(NSRange)range replacementString:(NSString *)string&#123; NSCharacterSet *cs; cs = [[NSCharacterSet characterSetWithCharactersInString:NUMBERS]invertedSet]; NSString *filtered = [[string componentsSeparatedByCharactersInSet:cs]componentsJoinedByString:@&quot;&quot;]; //按cs分离出数组,数组按@&quot;&quot;分离出字符串 BOOL canChange = [string isEqualToString:filtered]; return canChange;&#125; 上面那个NUMBERS是一个宏，可以在文件顶部定义：#define NUMBERS @”0123456789
