链表实现数据的存储，解决数组存储数据的不便利性 实例代码如下： 1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859606162636465666768/* films2.c -- 使用结构链接表 */#include &lt;stdio.h&gt;#include &lt;stdlib.h&gt; /* 提供malloc()原型 */#include &lt;string.h&gt; /* 提供strcpy()原型 */#define TSIZE 45 /* 存放片名的数组大小 */struct film&#123; char title[TSIZE]; int rating; struct film *next; /* 指向链表的下一个结构 */&#125;;int main(void)&#123; struct film *head = NULL; struct film *prev, *current; char input[TSIZE]; /* 手机并存数信息 */ puts(&quot;Enter first movie title: &quot;); while(gets(input) != NULL &amp;&amp; input[0] != &#x27;\0&#x27;) &#123; current = (struct film *) malloc(sizeof(struct film)); if(head == NULL) /* 第一个结构 */ &#123; head = current; &#125; else /* 后续结构 */ &#123; prev-&gt;next = current; &#125; current-&gt;next = NULL; strcpy(current-&gt;title, input); puts(&quot;Enter your rating &lt;0-10&gt;: &quot;); scanf(&quot;%d&quot;, &amp;current-&gt;rating); while(getchar() != &#x27;
&#x27;) &#123; continue; &#125; puts(&quot;Enter next movie title (empty line to stop)&quot;); prev = current; &#125; /* 给出电影的列表 */ if(head == NULL) &#123; printf(&quot;No data entered. &quot;); &#125; else &#123; printf(&quot;Here is the movie list :
&quot;); &#125; current = head; while(current != NULL) &#123; printf(&quot;Movie: %s Rating: %d
&quot;,current-&gt;title,current-&gt;rating); current = current-&gt;next; &#125; /* 任务完成，因此释放所分配的内存 */ current = head; while(current != NULL) &#123; free(current); current = current-&gt;next; &#125; printf(&quot;Bye!
&quot;);&#125;

